import * as G from './game.js';
import {Workshop} from './scene.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const KEY='ember-edge-save-v1';let state=G.newGame(),tab='forge',scene,sound=false,audioCtx,quench='oil',toastTimer,phase=0,last=performance.now(),saveElapsed=0,meterStart=performance.now();
try{const saved=localStorage.getItem(KEY);if(saved)state=G.restore(saved);}catch{$('#save-status').textContent='未能读取存档，已启用新工坊';}
try{scene=new Workshop($('#world'));}catch(e){console.error(e);$('#world').innerHTML='<div class="fallback">3D 场景未能启动。<br>请启用浏览器硬件加速，或换用支持 WebGL 的浏览器。<br>右侧仍可正常完成锻造。</div>';}
const fmt=n=>Math.round(n).toLocaleString('zh-CN');
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='进度自动保存在此浏览器';}catch{$('#save-status').textContent='浏览器存储不可用，请导出存档';}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function flash(text){const el=$('#floating-message');el.textContent=text;el.classList.remove('show');void el.offsetWidth;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1300);}
function tone(type){if(!sound)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.connect(gain);gain.connect(audioCtx.destination);const t=audioCtx.currentTime;osc.type=type==='hit'?'triangle':'sine';osc.frequency.setValueAtTime(type==='hit'?960:type==='break'?130:640,t);osc.frequency.exponentialRampToValueAtTime(type==='hit'?130:type==='break'?40:960,t+.18);gain.gain.setValueAtTime(.13,t);gain.gain.exponentialRampToValueAtTime(.001,t+.32);osc.start(t);osc.stop(t+.35);}catch{}}
function action(fn){try{const result=fn();save();render();return result;}catch(e){toast(e.message);return null;}}
function glyph(id,cls='sword-glyph'){const wide=id==='greatsword'||id==='falchion',thin=id==='rapier';return '<svg class="'+cls+'" viewBox="0 0 48 48" aria-hidden="true"><path d="M'+(thin?22:wide?18:21)+' 31V10L24 3L'+(thin?26:wide?30:27)+' 10V31Z" fill="currentColor" opacity=".85"/><path d="M14 32H34M24 33V43M20 44H28" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg>';}
function attrs(c){const a=G.attributes(c);return [['硬度',a.hard],['锋利',a.sharp],['韧性',a.tough],['重量',a.weight]].map(([name,v])=>'<div class="attribute-row"><span>'+name+'</span><div class="attribute-bar"><i style="width:'+(name==='重量'?Math.min(v/4*100,100):v)+'%"></i></div><b>'+v+(name==='重量'?' kg':'')+'</b></div>').join('');}
function current(){return state.session||state.selection;}
function recipeHeader(){const c=current(),o=G.ORES.find(x=>x.id===c.ore),sh=G.SHAPES.find(x=>x.id===c.shape);return '<p class="panel-description">'+o.name+' · '+G.GRADES[c.grade].name+'品位 / '+sh.name+'</p>';}
function renderPrepare(){const a=state.selection,o=G.ORES.find(x=>x.id===a.ore),sh=G.SHAPES.find(x=>x.id===a.shape),stock=state.inventory[o.id][a.grade],locked=o.tier>state.furnace+1;
return '<div class="panel-heading"><h2>开始一把新剑</h2><span>准备工序</span></div><p class="panel-description">选好材料，为剑赋予最初的性格。</p><div class="field-label"><span>01 / 选择矿石</span><small>库存 '+stock+' 份</small></div><div class="ore-select"><span class="ore-icon" style="--ore:'+o.color+'">◈</span><div><b>'+o.name+'</b><small>熔点 '+fmt(o.melt)+'°C · '+G.GRADES[a.grade].name+'品位</small></div><span class="pill">'+(locked?'炉温不足':'可熔炼')+'</span></div><div class="selectors"><select id="ore" aria-label="选择矿石">'+G.ORES.map(x=>'<option value="'+x.id+'" '+(x.id===a.ore?'selected':'')+'>'+x.name+' · '+state.inventory[x.id].reduce((a,b)=>a+b,0)+' 份</option>').join('')+'</select><select id="grade" aria-label="矿石品位">'+G.GRADES.map((x,i)=>'<option value="'+i+'" '+(i===a.grade?'selected':'')+'>'+x.name+' ×'+state.inventory[o.id][i]+'</option>').join('')+'</select></div><div class="field-label"><span>02 / 选择剑形</span><small>消耗 '+sh.cost+' 份矿石</small></div><div class="shape-grid">'+G.SHAPES.map(x=>'<button class="shape-option '+(x.id===a.shape?'selected':'')+'" data-shape="'+x.id+'" aria-pressed="'+(x.id===a.shape)+'" title="'+x.desc+'">'+glyph(x.id)+'<b>'+({longsword:'长剑',greatsword:'双手剑',rapier:'细剑',katana:'弧刃刀',falchion:'阔刃剑'}[x.id])+'</b><small>'+x.tag+'</small></button>').join('')+'</div><div class="field-label"><span>03 / 熔炼方式</span><small>影响剑坯属性</small></div><div class="method-grid">'+G.METHODS.map(x=>'<button class="method-option '+(x.id===a.method?'selected':'')+'" data-method="'+x.id+'" aria-pressed="'+(x.id===a.method)+'">'+x.name+'<small>'+x.desc+'</small></button>').join('')+'</div><p class="recipe-note">'+(locked?'需要 Lv.'+o.tier+' 熔炉才能熔化此矿石。':stock<sh.cost?'矿石不足，可在矿石商会购买或免费采集。':sh.desc+'。备料完成，炉火正旺。')+'</p><button class="primary" id="start" '+(locked||stock<sh.cost?'disabled':'')+'>♨ 入炉熔炼 <small>消耗 '+sh.cost+' 份矿石</small></button>'+(locked?'<button class="secondary" data-go="upgrades">前往升级熔炉</button>':stock<sh.cost?'<button class="secondary" data-go="market">前往矿石商会</button>':'');}
function renderSmelt(){const c=state.session,o=G.ORES.find(x=>x.id===c.ore),max=G.FURNACES[state.furnace].max;return '<div class="panel-heading"><h2>掌控炉火</h2><span>熔炼工序</span></div>'+recipeHeader()+'<div class="temperature"><strong id="temp">'+fmt(c.temp)+'</strong><span>°C</span><p id="temp-status">正在升温</p></div><div class="heat-bar"><div class="heat-zone" style="left:'+o.melt/max*100+'%;width:'+85/max*100+'%"></div><i id="heat-pointer" class="heat-pointer"></i></div><div class="scale-labels"><span>0°C</span><span>'+fmt(max)+'°C</span></div><div class="field-label"><span>风箱进气量</span><small id="air-value">'+Math.round(c.air)+'%</small></div><input id="air" type="range" min="0" max="100" step="1" value="'+c.air+'" aria-label="风箱进气量"><div class="field-label"><span>熔炼进度</span><small id="smelt-progress-text">'+Math.floor(c.progress)+'%</small></div><div class="progress-track"><i id="smelt-progress" style="width:'+c.progress+'%"></i></div><div class="smelt-note">理想温区 <b>'+fmt(o.melt)+'–'+fmt(o.melt+85)+'°C</b><br>调整风量，让指针保持在绿色区间。过热会增加杂质，低温则熔炼缓慢。</div><div class="field-label"><span>温控稳定度</span><small id="smelt-quality">等待矿石熔化</small></div><button id="cast" class="primary" '+(c.progress<100?'disabled':'')+'>'+(c.progress<100?'熔炼中…':'浇铸剑坯')+'</button><p class="recipe-note">熔炼完成后不会继续损失品质，可随时浇铸。</p>';}
function renderForge(){const c=state.session,r=G.risk(state),price=G.appraisal(c);return '<div class="panel-heading"><h2>百炼，方成锋</h2><span>锻打工序</span></div>'+recipeHeader()+'<div class="forge-summary"><div><strong>'+c.hits+'</strong><small>次锻打</small></div><span class="quality-pill">'+G.qualityName(c.quality)+' · '+Math.round(c.quality)+'</span></div>'+attrs(c)+'<div class="risk-box '+(r>.15?'danger':'')+'"><span>下一锤 · 断裂概率</span><b>'+Math.round(r*1000)/10+'%</b></div><div class="strike-meter"><i id="strike-pointer"></i></div><p class="meter-caption">指针越靠近金色中心，品质提升越多</p><button id="strike" class="primary">⚒ 挥锤锻打 <small>空格键</small></button><div class="quench-select" aria-label="淬火方式">'+[['oil','油淬 · 韧性'],['water','水淬 · 硬度'],['air','风冷 · 锋利']].map(([id,t])=>'<button data-quench="'+id+'" class="'+(quench===id?'selected':'')+'" aria-pressed="'+(quench===id)+'">'+t+'</button>').join('')+'</div><button id="finish" class="secondary" '+(c.hits<3?'disabled':'')+'>'+(c.hits<3?'再锻 '+(3-c.hits)+' 次即可淬火':'收锤淬火 · 完成此剑')+'</button><p class="recipe-note">当前估价约 '+fmt(price)+' 金币。'+(c.quality>=100?'品质已达上限，现在收手最划算。':'成功挥锤必定提升品质，失败则剑坯报废。')+'</p>';}
function renderFinished(){const c=state.session;return '<div class="panel-heading"><h2>锋芒，已成。</h2><span>'+G.qualityName(c.quality)+'品质</span></div>'+recipeHeader()+'<div class="result-art">'+glyph(c.shape)+'</div>'+attrs(c)+'<div class="breakdown">锻打 '+c.hits+' 次 · 熔炼纯净度 '+Math.round(c.smelt)+'%<br>品质 '+Math.round(c.quality)+'/100 · '+{oil:'油淬',water:'水淬',air:'风冷'}[c.quench]+'</div><div class="sale-price"><small>商会估价 · 综合属性评定</small><b>'+fmt(G.appraisal(c))+'</b><span>金币</span></div><button class="primary" id="sell">售卖此剑</button><button class="secondary" id="keep">收入我的作品</button>';}
function renderBroken(){return '<div class="panel-heading"><h2>过犹不及。</h2><span>锻造失败</span></div>'+recipeHeader()+'<div class="broken-art">⚡</div><p class="broken-copy">一声脆响，剑坯断裂。<br>你已完成 '+state.session.hits+' 次锻打。下一次，也许早一锤收手，就能留住那道锋芒。</p><button class="primary" id="recycle">回收废料 · 重新开始</button><p class="recipe-note">回收会返还少量金币。铁砧升级能延后风险出现，文火精炼和稳定温控也有助于剑坯品质。</p>';}
function renderMarket(){return '<div class="section-bar"><div><h2>好钢，始于好矿。</h2><p>选择材料与品位。高级矿石需要对应等级的熔炉，先备好炉火再买矿。</p></div><button class="mine-button" id="mine">⚒ 山间采矿 · 免费获得赤铁矿</button></div><div class="market-grid">'+G.ORES.map(o=>'<article class="market-card"><div class="card-title"><span class="eyebrow">'+o.en+'</span><span class="pill '+(o.tier>state.furnace+1?'locked':'')+'">Lv.'+o.tier+' 熔炉'+(o.tier>state.furnace+1?' · 未解锁':'')+'</span></div><div class="ore-icon" style="--ore:'+o.color+'">◈</div><h3>'+o.name+'</h3><p>'+o.desc+'</p><div class="mini-stats"><span>基础硬度<b>'+o.hard+'</b></span><span>基础锋利<b>'+o.sharp+'</b></span><span>基础韧性<b>'+o.tough+'</b></span></div><div class="inventory-line">熔点 '+fmt(o.melt)+'°C · 库存 '+state.inventory[o.id].join(' / ')+'（普通 / 精选 / 无瑕）</div><div class="buy-row"><select aria-label="'+o.name+'品位" data-buy-grade="'+o.id+'">'+G.GRADES.map((g,i)=>'<option value="'+i+'">'+g.name+'</option>').join('')+'</select><button class="primary" data-buy="'+o.id+'">◈ '+fmt(o.cost)+' · 购买</button></div></article>').join('')+'</div>';}
function renderUpgrades(){return '<div class="section-bar"><div><h2>工欲善其事。</h2><p>用每一把剑赚来的金币，让这间小工坊走得更远。设备需在当前锻造结束后升级。</p></div></div><div class="upgrade-grid">'+['furnace','anvil'].map(type=>{const list=type==='furnace'?G.FURNACES:G.ANVILS,level=state[type],now=list[level],next=list[level+1];return '<article class="upgrade-card"><span class="eyebrow">'+(type==='furnace'?'THE FURNACE':'THE ANVIL')+'</span><div class="upgrade-icon">'+(type==='furnace'?'♨':'⚒')+'</div><h3>'+now.name+' <span class="pill">Lv.'+(level+1)+'</span></h3><p>'+(type==='furnace'?'更炽热的炉火，唤醒更珍贵的金属。':'更稳固的铁砧，承受更精密的千锤百炼。')+'</p><div class="level-track">'+list.map((_,i)=>'<i class="'+(i<=level?'on':'')+'"></i>').join('')+'</div><div class="upgrade-detail"><span>'+(type==='furnace'?'最高炉温':'安全锻打次数')+'</span><b>'+(type==='furnace'?fmt(now.max)+'°C':(5+level*2)+' 次')+'</b></div><div class="upgrade-detail"><span>下一级</span><b>'+(next?next.name:'已登峰造极')+'</b></div><div class="upgrade-detail"><span>'+(type==='furnace'?'解锁矿石':'升级效果')+'</span><b>'+(next?(type==='furnace'?G.ORES.filter(o=>o.tier===level+2).map(o=>o.name).join('、'):'安全次数 +2 · 品质增益提高'):'最高等级')+'</b></div><button class="primary" data-upgrade="'+type+'" '+(!next||state.session||state.money<next.cost?'disabled':'')+'>'+(next?'升级设备 · '+fmt(next.cost)+' 金币':'大师设备 · 已满级')+'</button>'+(next&&state.money<next.cost?'<p class="recipe-note">还差 '+fmt(next.cost-state.money)+' 金币。</p>':'')+'</article>';}).join('')+'</div>';}
function renderCollection(){if(!state.collection.length)return '<div class="empty-state"><span>⚔</span><h2>你的名剑，还在炉火之中。</h2><p>完成锻造后选择「收入我的作品」，在这里收藏或售卖。</p><button class="primary" data-go="forge">回到锻造工坊</button></div>';return '<div class="section-bar"><div><h2>每一道锤痕，都有来处。</h2><p>共 '+state.collection.length+' 把作品，可随时交由商会收购。</p></div></div><div class="collection-grid">'+state.collection.map(c=>'<article class="market-card"><div class="card-title"><h3>'+G.SHAPES.find(x=>x.id===c.shape).name+'</h3><span class="quality-pill">'+G.qualityName(c.quality)+'</span></div><div class="result-art">'+glyph(c.shape)+'</div><p>'+G.ORES.find(o=>o.id===c.ore).name+' · '+G.GRADES[c.grade].name+' · '+c.hits+' 次锻打</p>'+attrs(c)+'<button class="primary" data-sell="'+c.id+'">售卖 · '+fmt(G.appraisal(c))+' 金币</button></article>').join('')+'</div>';}
function render(){const stage=state.session?.stage||'prepare';$$('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#forge-view').hidden=tab!=='forge';$('#secondary-view').hidden=tab==='forge';$('#page-title').textContent={forge:'每一把好剑，都始于炉火。',market:'寻一块好矿，铸一柄好剑。',upgrades:'从山间小炉，到传奇工坊。',collection:'此间藏锋，皆出你手。'}[tab];$('#money').textContent=fmt(state.money);$('#collection-count').textContent=state.collection.length;$('#rank-progress').textContent=state.stats.sold+' 把成交';$('#rank-name').textContent=state.stats.sold>=30?'铸剑宗师':state.stats.sold>=12?'资深铁匠':state.stats.sold>=3?'熟练匠人':'初入铁砧';$('#stat-crafted').innerHTML=fmt(state.stats.crafted)+' <span>把</span>';$('#stat-best').innerHTML=fmt(state.stats.best)+' <span>金币</span>';$('#stat-income').innerHTML=fmt(state.stats.income)+' <span>金币</span>';$('#furnace-name').textContent=G.FURNACES[state.furnace].name+' · Lv.'+(state.furnace+1);$('#furnace-cap').textContent='最高 '+fmt(G.FURNACES[state.furnace].max)+'°C';const index=['prepare','smelting','forging','finished'].indexOf(stage==='broken'?'forging':stage);$$('.step').forEach((s,i)=>{s.classList.toggle('active',i===index);s.classList.toggle('done',i<index)});if(tab==='forge'){$('#work-panel').innerHTML=({prepare:renderPrepare,smelting:renderSmelt,forging:renderForge,finished:renderFinished,broken:renderBroken}[stage])();}else{$('#secondary-view').innerHTML=({market:renderMarket,upgrades:renderUpgrades,collection:renderCollection}[tab])();}const panel=$('#work-panel');panel.classList.toggle('preparing',stage==='prepare');if(tab==='forge'&&stage==='prepare'){const buttons=[...panel.children].filter(e=>e.matches('button')),scroll=document.createElement('div'),actions=document.createElement('div');scroll.className='panel-scroll';actions.className='panel-actions';[...panel.childNodes].filter(n=>!buttons.includes(n)).forEach(n=>scroll.append(n));buttons.forEach(b=>actions.append(b));panel.append(scroll,actions);}scene?.setState(state);}
function navigate(next){tab=next;render();if(tab==='forge')requestAnimationFrame(()=>scene?.resize());}
function strike(){if(tab!=='forge'||$('#help-dialog').open||state.session?.stage!=='forging')return;const acc=1-Math.abs(phase-.5)*2;const r=action(()=>G.strike(state,acc));if(!r)return;scene?.hit(r.broken);if(r.broken){tone('break');flash('剑坯断裂');}else{tone('hit');flash((r.perfect?'完美锻打':'锻打成功')+' +'+r.gain.toFixed(1));}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
if(b.dataset.tab)navigate(b.dataset.tab);
if(b.dataset.go)navigate(b.dataset.go);
if(b.dataset.shape)action(()=>state.selection.shape=b.dataset.shape);
if(b.dataset.method)action(()=>state.selection.method=b.dataset.method);
if(b.dataset.quench){quench=b.dataset.quench;render();}
if(b.dataset.buy){const id=b.dataset.buy,grade=Number($('[data-buy-grade="'+id+'"]').value);action(()=>{const cost=G.buy(state,id,grade);toast('购入'+G.GRADES[grade].name+G.ORES.find(o=>o.id===id).name+' · −'+cost+' 金币');tone('buy');});}
if(b.dataset.upgrade)action(()=>{const u=G.upgrade(state,b.dataset.upgrade);toast('已升级为'+u.name);tone('buy');});
if(b.dataset.sell)action(()=>{const n=G.sell(state,b.dataset.sell);toast('作品售出 · +'+fmt(n)+' 金币');tone('buy');});
switch(b.id){
case 'start':action(()=>{G.start(state);flash('矿石入炉');});break;
case 'cast':action(()=>{G.cast(state);meterStart=performance.now();flash('剑坯浇铸完成');tone('buy');});break;
case 'strike':strike();break;
case 'finish':action(()=>{G.finish(state,quench);scene?.spark(.1,1.8,.9,28);flash('淬火成剑');tone('buy');});break;
case 'sell':action(()=>{const n=G.sell(state);toast('成交！获得 '+fmt(n)+' 金币');tone('buy');});break;
case 'keep':action(()=>{G.keep(state);toast('作品已收入陈列架');});break;
case 'recycle':action(()=>{const n=G.recycle(state);toast('废料回收 · +'+n+' 金币');});break;
case 'mine':action(()=>{G.mine(state);toast('采集成功 · 普通赤铁矿 +1');});break;
case 'sound':sound=!sound;b.textContent=sound?'♪':'♫';b.setAttribute('aria-label',sound?'关闭音效':'开启音效');b.title=sound?'关闭音效':'开启音效';tone('buy');toast(sound?'锻打音效已开启':'音效已关闭');break;
case 'help':$('#help-dialog').showModal();break;
case 'reset-camera':scene?.reset();break;
case 'save-export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='炉火与锋刃-存档.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('存档已导出');break;}
}
if(b.classList.contains('close-dialog')||b.classList.contains('close-help'))$('#help-dialog').close();
});
document.addEventListener('change',e=>{if(e.target.id==='ore')action(()=>state.selection.ore=e.target.value);if(e.target.id==='grade')action(()=>state.selection.grade=Number(e.target.value));if(e.target.dataset.buyGrade){const o=G.ORES.find(o=>o.id===e.target.dataset.buyGrade),g=G.GRADES[Number(e.target.value)];$('[data-buy="'+o.id+'"]').textContent='◈ '+fmt(Math.ceil(o.cost*g.mult))+' · 购买';}});
document.addEventListener('input',e=>{if(e.target.id==='air'&&state.session?.stage==='smelting'){state.session.air=Number(e.target.value);$('#air-value').textContent=e.target.value+'%';}});
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement?.tagName)&&state.session?.stage==='forging'&&tab==='forge'&&!$('#help-dialog').open){e.preventDefault();strike();}});
$('#save-import').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>1024*1024)throw Error('存档文件过大');const next=G.restore(await file.text());if(!confirm('导入存档会替换当前浏览器中的进度，是否继续？'))return;state=next;save();render();toast('存档已恢复');}catch(err){toast('导入失败：'+err.message);}finally{e.target.value='';}});
document.addEventListener('visibilitychange',()=>{save();last=performance.now();});window.addEventListener('pagehide',save);
function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;phase=(Math.sin((now-meterStart)*.0028)+1)/2;if(!document.hidden){G.tickSmelt(state,dt);if(tab==='forge'){scene?.update(dt);const c=state.session;if(c?.stage==='smelting'){$('#temp').textContent=fmt(c.temp);const o=G.ORES.find(o=>o.id===c.ore),inside=c.temp>=o.melt&&c.temp<=o.melt+85;$('#temp-status').textContent=c.progress>=100?'熔炼完成 · 可以浇铸':inside?'理想温区 · 材料正在融合':c.temp>o.melt+85?'温度过高 · 减小风量':'温度偏低 · 增大风量';$('#temp-status').style.color=inside?'var(--mint)':'var(--gold)';$('#heat-pointer').style.left=c.temp/G.FURNACES[state.furnace].max*100+'%';$('#smelt-progress').style.width=c.progress+'%';$('#smelt-progress-text').textContent=Math.floor(c.progress)+'%';$('#smelt-quality').textContent=c.progress<5?'等待矿石熔化':Math.round(c.good/G.METHODS.find(m=>m.id===c.method).time*100)+'% 有效精炼';if(c.progress>=100){$('#cast').disabled=false;$('#cast').textContent='浇铸剑坯';}}else if(c?.stage==='forging'){const p=$('#strike-pointer');if(p)p.style.left=phase*100+'%';}}
saveElapsed+=dt;if(saveElapsed>2){save();saveElapsed=0;}}requestAnimationFrame(frame);}
render();requestAnimationFrame(frame);
const context=document.modelContext;if(context?.registerTool){const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});for(const tool of [{name:'read_forge_status',title:'查看锻造进度',description:'Read this browser’s forge, inventory, equipment, active sword and coins without changing the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({money:state.money,furnace:state.furnace+1,anvil:state.anvil+1,inventory:state.inventory,stage:state.session?.stage||'prepare',hits:state.session?.hits||0,nextStrikeRisk:G.risk(state)})},{name:'mine_basic_ore',title:'采集赤铁矿',description:'Collect one free basic iron ore using the visible mining action; has a 3.5 second cooldown.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:(input)=>{if(!input||Object.keys(input).length)throw Error('This action accepts no arguments');G.mine(state);save();render();return{iron:state.inventory.iron[0]};}}]){try{Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}}

